package com.mo.economy_system.target.neoforge1211.protocol;
import com.mo.economy_system.EconomySystem;import com.mo.economy_system.common.market.*;import com.mo.economy_system.common.network.RemoveSalesOrderMessage;import com.mo.economy_system.core.economy_system.market.MarketSavedData;import com.mo.economy_system.network.MarketInvalidationBroadcaster;import com.mo.economy_system.platform.EconomyServices;import net.minecraft.network.chat.Component;import net.minecraft.server.level.ServerPlayer;import net.neoforged.neoforge.network.handling.IPayloadContext;import java.util.*;
public final class NeoForge1211RemoveSalesOrderHandler{private NeoForge1211RemoveSalesOrderHandler(){}public static void handle(RemoveSalesOrderMessage m,IPayloadContext c){c.enqueueWork(()->{if(!(c.player()instanceof ServerPlayer actor))return;MarketSavedData data=MarketSavedData.getInstance(actor.serverLevel());RemoveSalesOrderOutcome o=RemoveSalesOrderService.execute(m,new RemoveSalesOrderService.Context(actor.getUUID(),actor.hasPermissions(2),order->EconomyServices.platform().itemStacks().restoreSnapshot(order.item(),actor.registryAccess()).orElseThrow(),id->{ServerPlayer p=actor.server.getPlayerList().getPlayer(id);return p==null?Optional.empty():Optional.of(new NeoForge1211PurchaseSalesOrderHandler.InventoryAdapter(p));},new Repo(data),(trade,a,owner,op,stage,result,inv,order,e)->EconomySystem.LOGGER.error("Sales removal failure tradeId={} actor={} owner={} stage={} result={}",trade,a,owner,stage,result,e)));try{actor.sendSystemMessage(Component.translatable(RemoveSalesOrderFeedback.key(o.result())));}catch(RuntimeException e){EconomySystem.LOGGER.error("Removal feedback failed",e);}if(o.marketChanged())try{MarketInvalidationBroadcaster.broadcast(actor);}catch(RuntimeException e){EconomySystem.LOGGER.error("Removal invalidation failed",e);}});}private record Repo(MarketSavedData d)implements RemoveSalesOrderService.Repository{public MarketOrder find(UUID id){return d.getOrder(id);}public SalesOrderRemovalResult removeSalesTransactional(UUID id){return d.removeSalesTransactional(id);}}}
